class FuturesOrderEvent(TypedDict):
  """One futures order lifecycle push -- the unwrapped `data` field of the raw WebSocket frame (`SocketStreamClient.authed_subscribe` extracts `data` before handing the stream to the caller; see `spec/core.md`'s WebSocket section). Shared verbatim by `streams.futures.order` (per-symbol, wire `subject: "orderChange"`) and `streams.futures.all_orders` (every symbol, wire `subject: "symbolOrderChange"`) -- KuCoin's own docs state the two payloads are identical, differing only in which topic/subject delivered them, both stripped by the transport before this schema applies."""

  symbol: str
  """Contract symbol, for example `XBTUSDTM`."""
  orderId: str
  """Order id assigned by the matching system."""
  clientOid: NotRequired[str]
  """Client-assigned order id, echoed back from the placement request. Present when the order was placed with one."""
  orderType: NotRequired[Literal['limit', 'market']]
  """User-specified order type."""
  side: Literal['buy', 'sell']
  """Order side."""
  marginMode: Literal['ISOLATED', 'CROSS']
  """Margin mode the order was placed under."""
  positionSide: NotRequired[str]
  """Which side of a Hedge Mode position this order applies to. KuCoin's own docs-new page for this channel lists it only as "`BOTH` or directional designation" -- not a full enumeration -- so left a plain string rather than a guessed enum, matching `FuturesAddOrderLimit.positionSide`'s same treatment for the same reason."""
  type: Literal['open', 'match', 'update', 'filled', 'canceled']
  """Event driving this push."""
  status: Literal['open', 'match', 'done']
  """Order status: `open` (resting in the order book), `match` (a taker order currently executing), `done` (fully executed, filled or canceled)."""
  orderTime: TimestampNanos
  """Unix nanoseconds when the gateway received the order -- unlike Spot/Margin's Order V2 channel, whose analogous field is milliseconds; per this channel's own docs page."""
  ts: TimestampNanos
  """Unix nanoseconds when the matching engine generated this push."""
  size: int
  """User-specified order size, in contracts."""
  price: Decimal
  """Order price."""
  filledSize: int
  """Cumulative amount filled, in contracts."""
  remainSize: int
  """Remaining unfilled size, in contracts."""
  canceledSize: int
  """Cumulative amount canceled, in contracts."""
  matchPrice: NotRequired[Decimal]
  """Execution price of this fill. Present only on `match`."""
  matchSize: NotRequired[int]
  """Amount matched in this fill, in contracts. Present only on `match`."""
  tradeId: NotRequired[str]
  """Trade id generated by the matching engine for this fill. Present only on `match`."""
  liquidity: NotRequired[Literal['taker', 'maker']]
  """Liquidity role of this fill. Present only on `match`."""
  feeType: NotRequired[Literal['makerFee', 'takerFee']]
  """Actual fee type charged for this fill. Present only on `match`."""
  oldSize: NotRequired[Decimal]
  """Order size before this update. Present only on `update`."""
  tradeType: Literal['trade', 'liquid', 'adl']
  """Which book this order executes against."""


